const clock = z.number().int().min(0).max(3600).nullish();
const playerIndex = z.number().int().min(0).max(MAX_PLAYERS - 1);
export const FOUL_KINDS = ['personal', 'shooting', 'technical', 'unsportsmanlike'] as const;

